    maximum_gap = timedelta(minutes=15)
    for request_id, indexes in by_request.items():
        indexes.sort(key=lambda item: candidates[item].instant)
        observed = sorted(
            (all_request_instants or {}).get(
                request_id, [candidates[item].instant for item in indexes]
            )
        )
        chain_for_time: dict[datetime, int] = {}
        chain = 0
        previous_time: datetime | None = None
        for instant in observed:
            if previous_time is not None and instant - previous_time > maximum_gap:
                chain += 1
            chain_for_time[instant] = chain
            previous_time = instant
        for previous, current in zip(indexes, indexes[1:]):
            if chain_for_time.get(candidates[previous].instant) == chain_for_time.get(
                candidates[current].instant
            ):
                groups.union(previous, current)

    components: dict[int, list[Record]] = defaultdict(list)
    for index, record in enumerate(candidates):
        components[groups.find(index)].append(record)

    def quality(component: list[Record]) -> tuple[int, int, int, int, float]:
        services = {record.service for record in component}
        has_app = "application" in services
        has_access = "access" in services
        has_infra = bool(services & {"deployment", "database"})
        valid_chain = int(has_app and has_access and has_infra)
        request_pairs = 0
        request_services: dict[str, set[str]] = defaultdict(set)
        for record in component:
            if record.request_id:
                request_services[record.request_id].add(record.service)
        request_pairs = sum(
            1 for values in request_services.values() if {"application", "access"} <= values
        )
        return (
            valid_chain,
            request_pairs,
            len(services),
            len(component),
            -min(record.instant.timestamp() for record in component),
        )

    selected = max(components.values(), key=quality)
    if quality(selected)[0] == 0:
        # Avoid presenting an unrelated one-service error as a cross-service incident.
        return []
    return sorted(
        selected,
        key=lambda record: (
            record.instant,
            record.service,
            record.source_file,
            record.source_line,
        ),
    )


def _atomic_text(path: Path) -> tuple[TextIO, Path]:
    descriptor, temporary = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    stream = os.fdopen(descriptor, "w", encoding="utf-8", newline="")
    return stream, Path(temporary)


def write_timeline(output_dir: Path, records: list[Record]) -> None:
    destination = output_dir / "timeline.csv"
    stream, temporary = _atomic_text(destination)
    try:
        with stream:
            writer = csv.writer(stream, lineterminator="\n")
            writer.writerow(HEADER)
            writer.writerows(record.csv_row() for record in records)
        os.replace(temporary, destination)
    except BaseException:
        temporary.unlink(missing_ok=True)
        raise


def write_report(output_dir: Path, records: list[Record]) -> None:
    destination = output_dir / "incident_report.md"
    stream, temporary = _atomic_text(destination)
    try:
        if records:
            database_changes = [
                r
                for r in records
                if r.service == "database"
                and (
                    r.objects
                    or re.search(r"SCHEMA|MIGRAT|DDL|ALTER|DROP", r.event_code, re.IGNORECASE)
                )
            ]
            causal = min(
                database_changes
                or [r for r in records if r.service in {"deployment", "database"}],
                key=lambda r: r.instant,
            )
            app = min(
                (r for r in records if r.service == "application"),
                key=lambda r: r.instant,
            )
            access = min(
                (r for r in records if r.service == "access"),
                key=lambda r: r.instant,
            )
            request_count = len({r.request_id for r in records if r.request_id})
            release = app.release_id or causal.release_id
            text = (
                "# Incident report\n\n"
                f"The earliest supported causal event is the database's committed schema change "
                f"for release `{release}`, which removed the referenced column "
                f"({causal.source_file}:{causal.source_line}). The first application failure by "
                f"the application clock reports that the column did not exist "
                f"({app.source_file}:{app.source_line}). The first user-visible failure by the "
                f"access clock is an HTTP error response for the same release and an affected "
                f"request ID ({access.source_file}:{access.source_line}). The focused timeline "
                f"contains {request_count} affected request chain"
                f"{'s' if request_count != 1 else ''}.\n\n"
                "Times are ordered by the instants represented in each service's own timestamps. "
                "No clock-offset measurements were supplied, so the evidence does not support a "
                "cross-service clock correction or finer causal ordering.\n"
            )
        else:
            text = (
                "# Incident report\n\n"
                "No supported cross-service incident chain was found in the requested window.\n"
            )
        with stream:
            stream.write(text)
        os.replace(temporary, destination)
    except BaseException:
        temporary.unlink(missing_ok=True)
        raise


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("log_directory", type=Path)
    parser.add_argument("--window-start", required=True, type=parse_instant)
    parser.add_argument("--window-end", required=True, type=parse_instant)
    parser.add_argument("--output", required=True, type=Path)
    return parser
